      term.setCursorPos(2, y)
      term.setBackgroundColor(colors.black)
      term.setTextColor(colors.gray)
      term.write("(no metrics configured)")
      y = y + 1
    else
      for idx, m in ipairs(cfg.metrics) do
        if y >= h - 2 then break end
